        TimelineAuthoringCommand::RemoveTrack(id) => { let before = doc.tracks.len(); doc.tracks.retain(|value| &value.id != id); if before == doc.tracks.len() { return Err(TimelineAuthoringError::MissingTarget(id.to_string())); } }
